import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
r = 0
for bit in range(20):
    c = 0
    for x in a:
        if (x >> bit) & 1:
            c += 1
    if c % 3:
        r |= 1 << bit
print(r)

